def maxProfitCooldown(prices, c):
    n = len(prices)
    free = [0] * n
    hold = -10 ** 9
    for i in range(n):
        free[i] = free[i - 1] if i else 0
        if hold + prices[i] > free[i]:
            free[i] = hold + prices[i]
        j = i - c - 1
        base = free[j] if j >= 0 else 0
        if base - prices[i] > hold:
            hold = base - prices[i]
    return free[n - 1]
